protected boolean validatePriceDiscPct()
{
    boolean ret = next validatePriceDiscPct();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        RetailDiscountMultibuy multibuy = RetailDiscountMultibuy::find(this.multibuyId);
        if (multibuy.MultibuyDiscountType == RetailDiscountTypeEnum::UnitPriceDiscAmt)
        {
            ret = RetailMonetaryUtilities::isValidDiscountDealPriceAllowZero(this.priceDiscPct);
        }
    }

    return ret;
}
